        public virtual void SalesChangeDisposalSlipSearchGetStoreName(
            string corporateCD,
            DateTime? systemDate,
            string storeCD,
            out string storeName)
        {
            // 店舗名称公開検索条件Entity
            StoreNameDisclosureSearchConditionEntity storeNameDisclosureSearchConditionEntity =
                new StoreNameDisclosureSearchConditionEntity();

            // 店舗名称公開DataSet
            using (StoreNameDisclosureDataSet storeNameDisclosureDataSet = new StoreNameDisclosureDataSet())
            {
                // -- 検索条件のセット
                // 店舗名称公開検索条件Entity.基準日
                storeNameDisclosureSearchConditionEntity.BaseDate = systemDate;

                // 店舗名称公開検索条件Entity.法人コード
                storeNameDisclosureSearchConditionEntity.CorporationCode = corporateCD;

                // 店舗名称公開検索条件Entity.店舗コード
                storeNameDisclosureSearchConditionEntity.StoreCD = storeCD;

                // [共通部品]店舗取得ビジネスをインスタンス化
                ICmrStoreAPI business = 
                    (ICmrStoreAPI)ClassObjectUtil.GetBusinessInstance("BSCCMR01001", typeof(ICmrStoreAPI));

                // 店舗名称の取得ビジネス(BSCCMR01001000003)を呼び出す。
                business.GetStoreNameDisclosure(
                    "SA",
                    storeNameDisclosureSearchConditionEntity,
                    storeNameDisclosureDataSet);

                if (storeNameDisclosureDataSet == null ||
                    storeNameDisclosureDataSet.StoreNameDisclosure.Rows.Count == 0)
                {
                    throw RetailBusinessException.CreateInstance(ErrorKey.ERRCSARB0132, "指定した店舗");
                }

                // 店舗名称公開Ds.分類１名称（漢字）を戻り値にセットする。
                storeName = storeNameDisclosureDataSet.StoreNameDisclosure[0].StoreKanji;
            }
        }
