                char next = i + 1 < text.Length ? text[i + 1] : '\0';

                if (inLineComment)
                {
                    if (c == '\r' || c == '\n')
                    {
                        inLineComment = false;
                    }

                    continue;
                }

                if (inBlockComment)
                {
                    if (c == '*' && next == '/')
                    {
                        inBlockComment = false;
                        i++;
                    }

                    continue;
                }

                if (inString)
                {
                    if (inVerbatimString)
                    {
                        if (c == '"' && next == '"')
                        {
                            i++;
                        }
                        else if (c == '"')
                        {
                            inString = false;
                            inVerbatimString = false;
                        }
                    }
                    else
                    {
